{
  "units": [
    {
      "quote": "The goal is the best likeness that can reasonably be obtained",
      "scope_quotes": [
        "d. Infants pose a particular challenge."
      ],
      "kind": "recommendation",
      "meaning": "For infant photographs, the objective is to obtain the best likeness of the infant that can reasonably be achieved."
    },
    {
      "quote": "It is acceptable if the infant's eyes, particularly a newborn's, are partially or completely closed",
      "scope_quotes": [
        "d. Infants pose a particular challenge. The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "permission",
      "meaning": "In photographs of infants (especially newborns), having the eyes partially or completely closed is permissible."
    },
    {
      "quote": "The infant's head may be discreetly supported, e.g., a car seat with a white or off-white blanket behind the child",
      "scope_quotes": [
        "d. Infants pose a particular challenge. The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "permission",
      "meaning": "An infant's head is allowed to be discreetly supported, such as by using a car seat with a white or off-white blanket placed behind the child."
    },
    {
      "quote": "Head tilt is acceptable for infants",
      "scope_quotes": [
        "d. Infants pose a particular challenge. The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "permission",
      "meaning": "Head tilt is permitted in photographs of infants."
    },
    {
      "quote": "A parent’s face cannot be in the photograph of the infant",
      "scope_quotes": [
        "d. Infants pose a particular challenge. The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "prohibition",
      "meaning": "A parent's face is prohibited from appearing in the photograph of an infant."
    },
    {
      "quote": "You must request a new photograph if the photograph submitted does not meet the following requirements",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "A new photograph must be requested whenever a submitted photograph fails to satisfy the specified requirements."
    },
    {
      "quote": "The photograph must be in color",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:"
      ],
      "kind": "requirement",
      "meaning": "The submitted photograph is mandatory to be in color."
    },
    {
      "quote": "The photograph should be taken within six months of submitting the application, be a good likeness of and satisfactorily identify the applicant at the time of the application (see 22 CFR 51.26)",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:"
      ],
      "kind": "recommendation",
      "meaning": "The photograph should be taken within six months prior to application submission, represent a good likeness of the applicant, and satisfactorily identify the applicant at application time."
    },
    {
      "quote": "A photograph showing a change in hairstyle or facial hair from the identification document submitted is acceptable if it still is a good likeness of the applicant",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:"
      ],
      "kind": "permission",
      "meaning": "A photograph showing different hairstyle or facial hair compared to the submitted identification document is acceptable provided it remains a good likeness of the applicant."
    },
    {
      "quote": "Be aware that even if the certificate itself was recently issued, because of U.S. Citizenship and Immigration Services processing times, the photograph may not have been taken within six months of submitting the application",
      "scope_quotes": [
        "NOTE: Applicants may wish to re-use a passport photograph that is depicted on their submitted U.S Certificate of Citizenship or Certificate of Naturalization."
      ],
      "kind": "statement",
      "meaning": "When applicants seek to reuse a photo from a U.S. Certificate of Citizenship or Naturalization, the photograph might not have been taken within six months of application submission despite recent certificate issuance due to USCIS processing delays."
    },
    {
      "quote": "The photograph must be free of material damage",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:"
      ],
      "kind": "requirement",
      "meaning": "The photograph is required to have no material damage."
    },
    {
      "quote": "Material damage is any damage to the facial area that makes the photograph no longer a good likeness of the applicant (e.g., creases, large holes, and large smudges) or impedes the functioning of facial recognition (damage in the area of the eyes)",
      "scope_quotes": [
        "(6) The photograph must be free of material damage:"
      ],
      "kind": "definition",
      "meaning": "Material damage is defined as any facial area damage that renders the photo no longer a good likeness (such as creases, large holes, or large smudges) or that impairs facial recognition functions (such as eye area damage)."
    },
    {
      "quote": "Immaterial damage is any damage to the background, and non-material damage to the facial area (e.g., staple holes)",
      "scope_quotes": [
        "(6) The photograph must be free of material damage:"
      ],
      "kind": "definition",
      "meaning": "Immaterial damage is defined as background damage or non-material facial area damage, such as staple holes."
    },
    {
      "quote": "Immaterial damage is acceptable",
      "scope_quotes": [
        "(6) The photograph must be free of material damage:"
      ],
      "kind": "permission",
      "meaning": "Photographs possessing immaterial damage are permissible."
    },
    {
      "quote": "The applicant does not need to sign the photograph, as this often causes creases or smudges",
      "scope_quotes": [
        "(6) The photograph must be free of material damage:"
      ],
      "kind": "exemption",
      "meaning": "Applicants are not required to sign the photograph, because signing often creates creases or smudges."
    },
    {
      "quote": "For hand-carry applications, the acceptance agent signs the back of the photograph",
      "scope_quotes": [
        "(6) The photograph must be free of material damage:"
      ],
      "kind": "requirement",
      "meaning": "In the case of hand-carry applications, the acceptance agent must sign the reverse side of the photograph."
    },
    {
      "quote": "Consequently, the passport application may be returned to adjudication to request a new photograph even though the photograph appeared acceptable",
      "scope_quotes": [
        "(6) The photograph must be free of material damage:",
        "(d) A photograph that appears acceptable and undamaged in the system may have a defect that is apparent when the passport is printed."
      ],
      "kind": "permission",
      "meaning": "A passport application is permitted to be sent back to adjudication to request a replacement photograph if a defect emerges during printing, even if the photo seemed undamaged and acceptable in the system."
    },
    {
      "quote": "Eyeglasses are not acceptable unless they cannot be removed for medical reasons, e.g., the applicant has recently had ocular surgery and the eyeglasses are necessary to protect the applicant’s eyes",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:"
      ],
      "kind": "prohibition",
      "meaning": "Eyeglasses are prohibited in photographs unless they cannot be removed due to medical reasons, such as requiring eye protection following recent ocular surgery."
    },
    {
      "quote": "A medical statement signed by a medical professional/health practitioner must be requested in these rare circumstances",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "(1) Eyeglasses are not acceptable unless they cannot be removed for medical reasons, e.g., the applicant has recently had ocular surgery and the eyeglasses are necessary to protect the applicant’s eyes."
      ],
      "kind": "requirement",
      "meaning": "When eyeglasses cannot be removed for medical reasons, adjudicators are required to request a signed medical statement from a medical professional or health practitioner."
    },
    {
      "quote": "The frames of the eyeglasses must not cover the eye(s)",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "prohibition",
      "meaning": "If eyeglasses are permitted due to medical reasons, the frames are prohibited from covering the eye or eyes."
    },
    {
      "quote": "There must not be glare on eyeglasses that obscures the eye(s)",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "prohibition",
      "meaning": "If eyeglasses are permitted due to medical reasons, glare that obscures the eye or eyes is prohibited."
    },
    {
      "quote": "There must not be shadows or refraction from the eyeglasses that obscure the eye(s)",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "prohibition",
      "meaning": "If eyeglasses are permitted due to medical reasons, shadows or refraction obscuring the eye or eyes are prohibited."
    },
    {
      "quote": "Dark or tinted lenses are permitted if the medical statement also indicates that they are required",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "permission",
      "meaning": "Dark or tinted lenses are allowed only on the condition that the signed medical statement explicitly indicates that they are required."
    }
  ]
}
